function y=earliest_dispatch_kernel_v75(u,p,old)
%#codegen
% Interval-valued event segments with symbolic threshold contacts, never a
% root midpoint. See audit/Earliest_dispatch_derivation_v73.md for schema.
assert(all(isfinite([u;p;old])),'v73 finite domain');
assert(u(1)==1&&u(5)>0&&u(6)>=0&&u(7)>=0&&all(u(8:9)==0|u(8:9)==1),'v73 input domain');
assert(all(p([1 7 8 13 14 16 17 18])>0)&&p(7)<=1&&p(8)<=1&&p(6)>=0&& ...
    all(p([9 10 11 21 22 23 24])>=0)&&p(15)>0&&p(15)<=1,'v73 equipment domain');
assert(p(2)>-273.15&&p(2)<p(4)&&p(4)<p(5)&&p(5)<p(25)&&p(25)<p(3)&& ...
    p(19)<=p(4)&&p(6)*u(5)<=1,'v73 thermal/span domain');
P=@(v)[v v];C=P(p(1));Ta=P(p(2));cap=muliv(C,minusiv(P(p(3)),Ta));
cut=muliv(C,minusiv(P(p(4)),Ta));restart=muliv(C,minusiv(P(p(5)),Ta));stop=muliv(C,minusiv(P(p(25)),Ta));
y=zeros(1380,1);y(2)=75;y(73:75)=[u(5);u(7);u(8)+2*u(9)];y(76:100)=p;
if old(2)==0
    assert(u(10)>=0&&u(10)<cap(1)&&ismember(u(11),[0 1])&&u(12)>=0,'v73 initial domain');
    E=P(u(10));on=u(11);age=P(u(12));clock=P(0);tag=0;total=zeros(20,1);origin=E;ageCert=1;ageHi=u(12);ageErr=P(0);
else
    assert(old(2)==75&&all(old(76:100)==p),'v73 immutable policy');
    E=old(5:6)';on=old(7);age=old(8:9)';clock=old(10:11)';tag=old(12);total=old(31:50);origin=old(51:52)';ageCert=old(62);ageHi=old(63);ageErr=old(64:65)';
end
assert(E(1)>=0&&E(1)<=E(2)&&E(2)<cap(2)&&age(1)>=0&&age(1)<=age(2),'v73 retained bounds');
boundary=plusiv(clock,P(u(5)));assert(u(3)>clock(2)&&boundary(1)<=u(3)&&boundary(2)>=u(3),'v73 physical clock');
y(3:4)=E';y(51:52)=origin';y(58:59)=clock';y(60:61)=boundary';
Te=minusiv(minusiv(P(p(12)),P(p(13))),P(p(14)));a=muliv(P(p(15)),plusiv(Te,P(273.15)));
floor=plusiv(P(p(19)),P(p(20)));lf=minusiv(plusiv(floor,P(p(18))),Te);
assert(a(1)>0&&lf(1)>0,'v73 refrigerant domain');
sourceCap=muliv(P(u(7)),P(p(13)));
sourceLimit=muliv(sourceCap,plusiv(P(1),diviv(lf,a)));
waterLimit=muliv(P(p(16)),P(p(17)));
candidate=max(0,min([p(11),sourceLimit(1),waterLimit(1)]));
% Conservative binary allocation leaves room for the certified exact sum of
% separately rounded direct/charge ports. This is a power selection, not a
% relaxed physical guard or tolerance.
limit=max(0,candidate-8*eps(candidate));
y(66:71)=[sourceCap';sourceLimit';waterLimit'];
t=P(0);ports=zeros(20,1);finished=false;events=0;lastmode=0;
for slot=1:16
    assert(~finished,'v73 internal finished sequence');
    remaining=minusiv(P(u(5)),t);assert(remaining(1)>0,'v73 unresolved remaining duration');
    incoming=E;incomingAge=age;incomingOn=on;incomingTag=tag;
    potential=max(0,min(p(9),limit-min(u(6),limit)));
    belowStop=(tag==2||tag==3)||(tag==0&&E(2)<stop(1));
    canCharge=u(9)==1&&belowStop&&potential>0;
    request=u(6);if canCharge,request=request+potential;end
    sink=request>0;futureSink=u(6)>0||(u(9)==1&&potential>0);
    atRestart=tag==3||(tag==2)||(tag==0&&E(2)<=restart(1));
    reason=0;
    if on==1&&(limit==0||~sink),on=0;age=P(0);reason=3;
    elseif on==1&&u(8)==0
        assert(age(1)>=p(22)||(ageCert==1&&certifiedAge(ageHi,ageErr,p(22))),'v73 ON dwell not certified');on=0;age=P(0);reason=2;
    elseif on==0&&u(8)==1&&limit>0&&sink&&atRestart&&age(1)>=p(23)
        on=1;age=P(0);reason=1;
    end
    hp=0;if on==1,hp=min(request,limit);end
    direct=min(u(6),hp);charge=0;if canCharge,charge=min(potential,max(0,hp-direct));end
    dis=0;aboveCut=tag==1||tag==3||(tag==0&&E(1)>cut(2));
    if charge==0&&aboveCut,dis=min(p(10),max(0,u(6)-direct));end
    boiler=min(p(24),max(0,u(6)-direct-dis));unmet=max(0,u(6)-direct-dis-boiler);
    B=minusiv(muliv(P(p(7)),P(charge)),diviv(P(dis),P(p(8))));
    mode=0;if unmet>0,mode=5;elseif boiler>0,mode=4;elseif dis>0,mode=3;elseif charge>0,mode=2;elseif direct>0,mode=1;end
    candidates=zeros(3,15);enabled=[charge>0 dis>0 on==0&&u(8)==1&&limit>0&&futureSink];
    if enabled(1)
        deriv=minusiv(B,muliv(P(p(6)),stop));
        if deriv(1)>0,candidates(1,:)=certify_event_root_v73(E,B,p(6),stop,1,u(5),0,P(0))';
        elseif deriv(2)>0,assert(false,'v73 unresolved stop derivative');end
    end
    if enabled(2),candidates(2,:)=certify_event_root_v73(E,B,p(6),cut,-1,u(5),0,P(0))';end
    if enabled(3)
        if atRestart
            r=zeros(1,15);r(1)=3;r(8:9)=max(0,minusiv(P(p(23)),age));r(10:11)=r(8:9);r(13)=-1;r(14:15)=restart;candidates(3,:)=r;
        else
            deriv=minusiv(B,muliv(P(p(6)),restart));
            if tag==1&&all(B==0)&&p(6)>0&&p(25)-p(5)<=.5*(p(5)-p(2))
                candidates(3,:)=passive_contact_root_v73r2(p,u(5),p(23),age)';y(72)=1;
            elseif deriv(2)<0,candidates(3,:)=certify_event_root_v73(E,B,p(6),restart,-1,u(5),p(23),age)';
            elseif deriv(1)<0,assert(false,'v73 unresolved restart derivative');end
        end
    end
    duration=remaining;event=0;
    for j=1:3
        r=candidates(j,:);if r(1)==0,continue;end
        if r(1)==2
            % An unresolved root at the original macro span is harmless only
            % if the entire actual remaining trajectory is certainly before it.
            [tail,~]=flow(E,remaining,p(6),B);
            if j==1,before=tail(2)<stop(1);elseif j==2,before=tail(1)>cut(2);else,before=tail(1)>restart(2);end
            assert(before,'v73 unresolved event boundary');continue;
        end
        ready=r(10:11);
        if ready(1)>remaining(2),continue;end
        assert(ready(2)<remaining(1),'v73 unresolved event boundary');
        if event==0||ready(2)<duration(1),duration=ready;event=j;
        elseif ready(1)<=duration(2),assert(false,'v73 unresolved enabled event ordering');end
    end
    assert(duration(1)>0,'v73 zero-progress event');
    [endpoint,integral]=flow(E,duration,p(6),B);newtag=0;thermal=0;
    if event==1,endpoint=stop;newtag=1;thermal=1;
    elseif event==2,endpoint=cut;newtag=2;thermal=1;
    elseif event==3
        r=candidates(3,:);
        if r(1)==1&&r(2)>r(9),endpoint=restart;newtag=3;thermal=1;
        elseif r(8)>r(3)||r(1)==3
            % The age identity age+(minOFF-age)=minOFF is retained,
            % not reconstructed from independent interval endpoints.
            assert(endpoint(2)<=restart(2)||atRestart,'v73 dwell thermal readiness');
        else,assert(false,'v73 unresolved thermal/dwell ordering');end
        if thermal==1,assert(plusiv(age,duration)*[1;0]>=p(23),'v73 OFF dwell not certified');end
    end
    assert(endpoint(1)>=0&&endpoint(2)<cap(2),'v73 TES bounds');
    assert(dis==0||event==2||endpoint(1)>=cut(2),'v73 discharge cutoff');
    assert(charge==0||event==1||endpoint(2)<stop(1),'v73 charging stop');
    % The source rectangles cover the full event duration box. The exact
    % root/threshold relation is recorded; Cartesian evaluation only widens it.
    q=plusiv(P(direct),P(charge));src=P(0);work=P(0);
    % q <= S*(1+liftFloor/a), hot >= floor, a>0 imply source<=S.
    % Retain this relation instead of demanding disjoint widened boxes.
    assert(q(2)<=sourceLimit(1)&&q(2)<=waterLimit(1)&&q(2)<=p(11),'v73 selected power certificate');
    for cell=1:32
        t0=muliv(duration,P((cell-1)/32));t1=muliv(duration,P(cell/32));
        [e0,~]=flow(E,t0,p(6),B);[e1,~]=flow(E,t1,p(6),B);
        eh=[min(e0(1),e1(1)) max(e0(2),e1(2))];hot=plusiv(plusiv(Ta,diviv(eh,C)),P(p(17)));
        hot=[max(floor(1),hot(1)) max(floor(2),hot(2))];lift=minusiv(plusiv(hot,P(p(18))),Te);
        rate=muliv(q,diviv(a,plusiv(a,lift)));
        assert(lift(1)>0,'v73 positive work lift');
        % Intersection is justified by the selected-power/floor certificate.
        rate=[max(0,rate(1)) min(sourceCap(2),rate(2))];
        assert(rate(1)<=rate(2),'v73 finite source certificate intersection');
        wrate=muliv(q,diviv(lift,plusiv(a,lift)));
        work=plusiv(work,muliv(wrate,diviv(duration,P(32))));
        src=plusiv(src,muliv(rate,diviv(duration,P(32))));
    end
    assert(q(2)<=muliv(P(p(16)),P(p(17)))*[0;1],'v73 finite water capacity');
    heat=muliv(q,duration);standing=muliv(P(p(6)),integral);
    closs=muliv(minusiv(P(1),P(p(7))),muliv(P(charge),duration));
    dloss=muliv(minusiv(diviv(P(1),P(p(8))),P(1)),muliv(P(dis),duration));
    service=muliv(P(direct+dis+boiler),duration);back=muliv(P(boiler),duration);missing=muliv(P(unmet),duration);aux=muliv(P(p(21)),work);
    increment=[heat';src';work';standing';closs';dloss';service';back';missing';aux'];
    assert(all(increment>=0),'v73 nonnegative energy');
    seglaw=minusiv(minusiv(minusiv(minusiv(plusiv(E,plusiv(heat,back)),service),endpoint),standing),plusiv(closs,dloss));
    assert(seglaw(1)<=0&&seglaw(2)>=0,'v73 segment first law');
    offset=ports;for j=1:10,ix=2*j-1:2*j;ports(ix)=plusiv(ports(ix)',increment(ix)')';end
    elapsed=plusiv(t,duration);newage=plusiv(age,duration);outOn=on;
    if event==1,outOn=0;newage=P(0);elseif event==3,outOn=1;newage=P(0);end
    z=zeros(80,1);z(1:4)=[slot;mode;event;thermal];z(5:6)=t';z(7:8)=duration';z(9:10)=elapsed';
    z(11:14)=[E';endpoint'];z(15:18)=[age';newage'];z(19:23)=[on;outOn;incomingTag;newtag;reason];
    z(24:29)=[hp;direct;charge;dis;boiler;unmet];z(30:31)=B';z(32:51)=increment;z(52:71)=offset;
    if event>0,z(72:73)=candidates(event,2:3)';z(74:75)=candidates(event,8:9)';z(76:77)=candidates(event,14:15)';end
    z(78:80)=[incomingOn;incomingAge'];y(100+80*(slot-1)+(1:80))=z;
    % Exact binary macro durations admit a compensated age identity only
    % when no uncertain event intervened. Event ages keep their hull alone.
    if slot==1&&event==0
        if reason~=0,ageCert=1;ageHi=0;ageErr=P(0);end
        if ageCert==1,[ageHi,e]=twoSum(ageHi,u(5));ageErr=plusiv(ageErr,P(e));end
    else,ageCert=0;ageHi=0;ageErr=P(0);end
    E=endpoint;on=outOn;age=newage;tag=newtag;lastmode=mode;t=elapsed;
    if event==0
        % Exact held boundary identity t_start+(dt-t_start)=dt, with its
        % expression recorded in duration/offset fields. No midpoint used.
        t=P(u(5));finished=true;y(13)=slot;break;
    else,events=events+1;end
end
assert(finished,'v73 event segment budget');
for j=1:10,ix=2*j-1:2*j;total(ix)=plusiv(total(ix)',ports(ix)')';end
law=minusiv(minusiv(minusiv(minusiv(plusiv(origin,plusiv(total(1:2)',total(15:16)')),total(13:14)'),E),total(7:8)'),plusiv(total(9:10)',total(11:12)'));
assert(law(1)<=0&&law(2)>=0,'v73 cumulative first law');
y(1)=lastmode;y(5:6)=E';y(7)=on;y(8:9)=age';y(10:11)=boundary';y(12)=tag;y(14)=events;
y(15:30)=ports(1:16);y(31:50)=total;y(53:54)=law';y(55:56)=ports(17:18);y(57)=limit;y(62:65)=[ageCert;ageHi;ageErr'];
end
function [en,integral]=flow(initial,t,lambda,B)
[en,integral]=inventory_flow_v73(initial,t,lambda,B);
end
function ok=certifiedAge(hi,err,minimum)
[s,e]=twoSum(hi,-minimum);delta=plusiv([s s],plusiv([e e],err));ok=delta(1)>=0;
end
function [s,e]=twoSum(a,b)
s=a+b;bb=s-a;e=(a-(s-bb))+(b-bb);
assert(isfinite(s)&&isfinite(e),'v73 age certificate overflow');
end
function z=plusiv(x,y)
if all(x==0),z=y;elseif all(y==0),z=x;
elseif x(1)==x(2)&&y(1)==y(2)&&x(1)==-y(1),z=[0 0];
else,z=out([x(1)+y(1) x(2)+y(2)]);end
end
function z=minusiv(x,y)
if all(y==0),z=x;elseif x(1)==x(2)&&y(1)==y(2)&&x(1)==y(1),z=[0 0];else,z=out([x(1)-y(2) x(2)-y(1)]);end
end
function z=muliv(x,y)
if all(x==0)||all(y==0),z=[0 0];return;end
t=[x(1)*y(1) x(1)*y(2) x(2)*y(1) x(2)*y(2)];z=out([min(t) max(t)]);
end
function z=diviv(x,y)
assert(y(1)>0,'v73 positive denominator');if all(x==0),z=[0 0];return;end
if x(1)==x(2)&&y(1)==y(2)&&x(1)==y(1),z=[1 1];return;end
t=[x(1)/y(1) x(1)/y(2) x(2)/y(1) x(2)/y(2)];z=out([min(t) max(t)]);
end
function z=out(t)
assert(all(isfinite(t)),'v73 arithmetic overflow');z=[t(1)-2*eps(t(1)) t(2)+2*eps(t(2))];assert(all(isfinite(z)),'v73 outward overflow');
end

function z=certify_event_root_v73(E,B,lambda,target,direction,horizon,dwell,age)
%#codegen
% Held affine trajectory certificate. This returns a bracket, never a state reset.
% z=[status,tlo,thi,E(tlo).lo,hi,E(thi).lo,hi,wait.lo,hi,
%    ready.lo,hi,ordering,direction,target.lo,hi].
% status: 0 no crossing in horizon, 1 strict interior bracket,
% 2 unresolved contact/horizon, 3 already on the reached side.
% ordering: 0 no event, 1 ready strictly before horizon,
% 2 ordering unresolved, 3 ready strictly after horizon.
assert(all(isfinite([E B lambda target direction horizon dwell age])), 'v67 finite root domain');
assert(E(1)>=0&&E(1)<=E(2)&&B(1)<=B(2)&&target(1)>=0&&target(1)<=target(2)&& ...
    lambda>=0&&horizon>0&&lambda*horizon<=1&&ismember(direction,[-1 1])&& ...
    dwell>=0&&age(1)>=0&&age(1)<=age(2),'v67 root domain');
P=@(x)[x x];z=zeros(15,1);z(13)=direction;z(14:15)=target';
wait=minusiv(P(dwell),age);wait=max(0,wait);z(8:9)=wait';
before=@(v) (direction==1&&v(2)<target(1))||(direction==-1&&v(1)>target(2));
after=@(v) (direction==1&&v(1)>target(2))||(direction==-1&&v(2)<target(1));
reached=(direction==1&&E(1)>=target(2))||(direction==-1&&E(2)<=target(1));
if reached
    z(1)=3;z(4:7)=[E';E'];z(10:11)=wait';
elseif ~before(E)
    z(1)=2;z(2:3)=[0;horizon];z(12)=2;return;
else
    % Derivative sign at both ends certifies monotonicity on the entire
    % reachable segment. Equilibria and unresolved monotonicity are refused.
    d0=minusiv(B,muliv(P(lambda),E));d1=minusiv(B,muliv(P(lambda),target));
    if direction==1
        assert(d0(1)>0&&d1(1)>0,'v67 increasing root not certified');
    else
        assert(d0(2)<0&&d1(2)<0,'v67 decreasing root not certified');
    end
    endpoint=flow(E,P(horizon),lambda,B);
    if before(endpoint)
        z(1)=0;z(2:3)=horizon;z(4:7)=[endpoint';endpoint'];return;
    elseif ~after(endpoint)
        z(1)=2;z(2:3)=[0;horizon];z(4:7)=[E';endpoint'];z(12)=2;return;
    end
    % Search for the latest certainly-before and earliest certainly-after
    % witnesses independently. Ambiguous evaluations never choose a side.
    lo=0;right=horizon;
    for j=1:48
        mid=lo+(right-lo)/2;v=flow(E,P(mid),lambda,B);
        if before(v),lo=mid;else,right=mid;end
    end
    left=0;hi=horizon;
    for j=1:48
        mid=left+(hi-left)/2;v=flow(E,P(mid),lambda,B);
        if after(v),hi=mid;else,left=mid;end
    end
    elo=flow(E,P(lo),lambda,B);ehi=flow(E,P(hi),lambda,B);
    assert(before(elo)&&after(ehi)&&0<=lo&&lo<hi&&hi<horizon,'v67 root witnesses');
    z(1)=1;z(2:3)=[lo;hi];z(4:7)=[elo';ehi'];
    z(10:11)=[max(lo,wait(1));max(hi,wait(2))];
end
if z(11)<horizon,z(12)=1;elseif z(10)>horizon,z(12)=3;else,z(12)=2;end
end
function en=flow(initial,t,lambda,B)
[en,~]=inventory_flow_v73(initial,t,lambda,B);
end
function z=plusiv(x,y)
if all(x==0),z=y;elseif all(y==0),z=x;else,z=out([x(1)+y(1) x(2)+y(2)]);end
end
function z=minusiv(x,y)
if all(y==0),z=x;elseif x(1)==x(2)&&y(1)==y(2)&&x(1)==y(1),z=[0 0];else,z=out([x(1)-y(2) x(2)-y(1)]);end
end
function z=muliv(x,y)
if all(x==0)||all(y==0),z=[0 0];return;end
t=[x(1)*y(1) x(1)*y(2) x(2)*y(1) x(2)*y(2)];z=out([min(t) max(t)]);
end
function z=diviv(x,y)
assert(y(1)>0,'v67 positive root denominator');
if all(x==0),z=[0 0];return;end
t=[x(1)/y(1) x(1)/y(2) x(2)/y(1) x(2)/y(2)];z=out([min(t) max(t)]);
end
function z=out(t)
assert(all(isfinite(t)),'v67 root arithmetic overflow');z=[t(1)-2*eps(t(1)) t(2)+2*eps(t(2))];
assert(all(isfinite(z))&&z(1)<=z(2),'v67 root expansion overflow');
end

function monitor_temporal_commit_v77(u,p,old,y)
%#codegen
% Verify the candidate record BEFORE trace emission and retained-memory commit.
% Trace schema remains 75; model release is 77. No thermal solver is called.
assert(all(isfinite(y))&&y(2)==75&&all(y(76:100)==p),'v77 schema');
assert(y(13)>=1&&y(13)<=16&&y(13)==fix(y(13)),'v77 segment count');
assert(all(y(100+80*y(13)+1:end)==0),'v77 unused segments');
assert(all(y(73:75)==[u(5);u(7);u(8)+2*u(9)]),'v77 input binding');
if old(2)==0
    E=[u(10) u(10)];on=u(11);age=[u(12) u(12)];tag=0;clock=[0 0];
else
